contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 repaid_
    ) public payable {
        require(loanToCollateral_ > 0);
        require(duration_ > 0);
        require(amount_ > 0);

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        uint256 loanID = c.clearRequest(reqID, true, false);

        C.Loan memory beforeLoan = c.getLoan(loanID);

        uint256 beforeCollateral = beforeLoan.collateral;
        uint256 beforeAmount = beforeLoan.amount;

        uint256 repaid = repaid_ % (beforeAmount + 1);

        uint256 decollateralized = c.repayLoan(loanID, repaid);

        C.Loan memory afterLoan = c.getLoan(loanID);

        assert(
            decollateralized + afterLoan.collateral == beforeCollateral &&
            repaid + afterLoan.amount == beforeAmount
        );
    }

    receive() external payable {}
}

