contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(loanToCollateral != 0);

        uint256 beforeCount;
        try c.requests(0) returns (uint256, uint256, uint256, uint256, bool) {
            beforeCount = 1;
            uint256 i = 1;
            while (true) {
                try c.requests(i) returns (uint256, uint256, uint256, uint256, bool) {
                    beforeCount++;
                    i++;
                } catch {
                    break;
                }
            }
        } catch {
            beforeCount = 0;
        }

        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        (uint256 a, uint256 b, uint256 ltc, uint256 d, bool active) = c.requests(reqID);

        assert(reqID == beforeCount && active && a == amount && b == interest && ltc == loanToCollateral && d == duration);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 loanAmount_,
        uint256 loanInterest_,
        uint256 loanDuration_
    ) public {
        require(loanToCollateral_ > 0, "zero ltc");
        require(amount_ > 0, "zero amount");

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);
        uint256 loanID = c.clearRequest(reqID, false, false);

        C.Loan memory beforeLoan = c.getLoan(loanID);
        uint256 expectedInterest = c.interestFor(beforeLoan.amount, loanInterest_, loanDuration_);

        c.provideNewTermsForRoll(loanID, loanInterest_, loanToCollateral_, loanDuration_);

        bool reverted;
        try c.rollLoan(loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        C.Loan memory afterLoan = c.getLoan(loanID);

        assert(!reverted && afterLoan.amount == beforeLoan.amount + expectedInterest);
    }
}

