        uint256 collateralBefore = loanBefore.collateral;

        returned = c.repayLoan(loanID, repayAmount_);

        C.Loan memory loanAfter = c.getLoan(loanID);

        assert(
            loanAfter.amount == 0 &&
            loanAfter.collateral == 0 &&
            returned == collateralBefore
        );
    }
}

