contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(amount > 0 && interest > 0 && loanToCollateral > 0 && duration > 0);

        c.requestLoan(amount, interest, loanToCollateral, duration);
        c.clearRequest(0, false, false);

        C.Loan memory beforeLoan = c.getLoan(0);
        uint256 beforeExpiry = beforeLoan.expiry;
        uint256 beforeAmount = beforeLoan.amount;
        uint256 beforeCollateral = beforeLoan.collateral;
        uint256 expectedInterest = c.interestFor(beforeAmount, beforeLoan.request.interest, beforeLoan.request.duration);
        uint256 neededCollateral = c.collateralFor(beforeAmount, beforeLoan.request.loanToCollateral);
        uint256 expectedNewCollateral = neededCollateral > beforeCollateral ? neededCollateral - beforeCollateral : 0;

        bool reverted;
        try c.rollLoan(0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            C.Loan memory afterLoan = c.getLoan(0);
            assert(afterLoan.expiry == beforeExpiry + beforeLoan.request.duration);
            assert(afterLoan.amount == beforeAmount + expectedInterest);
            assert(afterLoan.collateral == beforeCollateral + expectedNewCollateral);
        } else {
            C.Loan memory afterLoan = c.getLoan(0);
            assert(afterLoan.expiry == beforeExpiry);
            assert(afterLoan.amount == beforeAmount);
            assert(afterLoan.collateral == beforeCollateral);
        }
    }

    receive() external payable {}
}

